package android.media;public class MediaPlayer {public static final int SEEK_CLOSEST=3;public static MediaPlayer last;public boolean playing,released,asyncSeek;public int seekCalls;public float volume;public long position;public int duration=120000;public OnPreparedListener prepared;public OnErrorListener error;public OnSeekCompleteListener seek;public OnCompletionListener completed;public MediaPlayer(){last=this;}public interface OnPreparedListener{void onPrepared(MediaPlayer p);}public interface OnErrorListener{boolean onError(MediaPlayer p,int a,int b);}public interface OnSeekCompleteListener{void onSeekComplete(MediaPlayer p);}public interface OnCompletionListener{void onCompletion(MediaPlayer p);}public void setAudioAttributes(AudioAttributes a){}public void setVolume(float a,float b){volume=a;}public void setDataSource(String p){}public void setOnErrorListener(OnErrorListener l){error=l;}public void setOnPreparedListener(OnPreparedListener l){prepared=l;}public void setOnSeekCompleteListener(OnSeekCompleteListener l){seek=l;}public void setOnCompletionListener(OnCompletionListener l){completed=l;}public void prepareAsync(){}public int getDuration(){return duration;}public int getAudioSessionId(){return 202;}public boolean isPlaying(){return playing;}public void pause(){playing=false;}public void start(){playing=true;}public int getCurrentPosition(){return (int)position;}public void seekTo(long p,int mode){seekCalls++;position=p;if(!asyncSeek&&seek!=null)seek.onSeekComplete(this);}public void release(){released=true;playing=false;}}